"use client";

import { loadFont } from "@remotion/google-fonts/Geologica";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_PARTS,
  DEFAULT_WHY,
  type NameGlossElementId,
  type NameGlossPart,
  nameGlossTimeline,
  partsOf,
  splitWords,
} from "./timeline";

const geologica = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export type { NameGlossPart };

export interface NameGlossProps {
  parts?: NameGlossPart[];
  why?: string;
  /** Frames between words as a gloss writes in. */
  stagger?: number;
  /** Frames held on the finished card; the glosses space out to fit the rest. */
  hold?: number;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the name and glosses. Load it yourself; Geologica by default. */
  fontFamily?: string;
  /** Size of the card, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches single name words rising, the move into
   * columns, each part's turn and single words of its gloss, and the "why"
   * line and its words, by the ids in `./timeline`. Frames on the scene
   * timeline, after `delay` and `speed`.
   */
  timing?: Timing<NameGlossElementId>;
}

const THEMES = {
  dark: { bg: "#0E3B43", ink: "#FFFFFF", accent: "#4FE3D0" },
  light: { bg: "#E8F6F5", ink: "#0B3138", accent: "#0F8C7E" },
} as const;

const FONT_PX = 200;
const NAME_W = 500;
const BODY_W = 400;
const NAME_TRACK = -0.04;
const BODY_TRACK = -0.015;
const BODY_LH = 1.2;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_MOVE = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const DIM = 0.38;

type Metrics = Record<string, number>;
const key = (w: number, s: string) => `${w}\u0002${s}`;

function measureAll(texts: string[], family: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("name-gloss: no 2d context");
  const out: Metrics = {};
  for (const weight of [NAME_W, BODY_W]) {
    ctx.font = `${weight} ${FONT_PX}px "${family}"`;
    for (const s of texts) {
      out[key(weight, s)] = ctx.measureText(s).width / FONT_PX;
    }
  }
  return out;
}

function useMetrics(texts: string[], family: string) {
  const id = `${family}\u0003${texts.join("\u0001")}`;
  const [state, setState] = useState<{ id: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("name-gloss: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      geologica.waitUntilDone(),
      document.fonts.load(`${NAME_W} 100px "${family}"`),
      document.fonts.load(`${BODY_W} 100px "${family}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({
          id,
          m: measureAll(id.split("\u0003")[1].split("\u0001"), family),
        });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [id, family, handle]);
  return state && state.id === id ? state.m : null;
}

function balanced(
  words: string[],
  width: (w: string) => number,
  space: number,
  limit: number,
) {
  const greedy = (lim: number) => {
    const lines: string[][] = [];
    let cur: string[] = [];
    let acc = 0;
    for (const w of words) {
      const ww = width(w);
      if (cur.length > 0 && acc + space + ww > lim) {
        lines.push(cur);
        cur = [w];
        acc = ww;
      } else {
        acc = cur.length > 0 ? acc + space + ww : ww;
        cur.push(w);
      }
    }
    if (cur.length > 0) lines.push(cur);
    return lines;
  };
  const count = greedy(limit).length;
  let lo = 0;
  let hi = limit;
  for (let i = 0; i < 18; i++) {
    const mid = (lo + hi) / 2;
    if (greedy(mid).length <= count) hi = mid;
    else lo = mid;
  }
  return greedy(hi);
}

interface Placed {
  x0: number;
  y0: number;
  x1: number;
  y1: number;
  colW: number;
  gloss: string[][];
  glossTop: number;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function NameGloss(props: NameGlossProps) {
  const {
    parts = DEFAULT_PARTS,
    why = DEFAULT_WHY,
    accent,
    ink,
    background,
    fontFamily = geologica.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    nameGlossTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const list = partsOf(parts);
  const m = useMetrics(
    [
      " ",
      ...list.map((p) => p.word),
      ...list.flatMap((p) => splitWords(p.gloss)),
      ...splitWords(why),
    ],
    fontFamily,
  );

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const n = list.length;
  const portrait = H > W * 1.1;
  const margin = W * (portrait ? 0.08 : 0.07);
  const avail = W - margin * 2;
  const gutter = W * (portrait ? 0.045 : 0.07);

  const nW = (s: string) =>
    m[key(NAME_W, s)] + NAME_TRACK * Array.from(s).length;
  const bW = (s: string) =>
    m[key(BODY_W, s)] + BODY_TRACK * Array.from(s).length;
  const wordEm = list.map((p) => nW(p.word));
  const nSpace = nW(" ");
  const bSpace = bW(" ");

  const moveEl = tl.get("move");
  const whyEl = tl.get("why");

  const easeAt = (tt: number, from: number, dur: number, curve = EASE_OUT) =>
    interpolate(tt, [from, from + dur], [0, 1], { ...CLAMP, easing: curve });
  const ease = (from: number, dur: number, curve = EASE_OUT) =>
    easeAt(t, from, dur, curve);
  // Whether a rise of `px` that starts at `from` is still travelling.
  const rising = (from: number, dur: number, px: number) =>
    Math.abs(easeAt(t + 1, from, dur) - easeAt(t, from, dur)) * px > 1e-3 ||
    Math.abs(easeAt(t, from, dur) - easeAt(t - 1, from, dur)) * px > 1e-3;

  let G = H * (portrait ? 0.05 : 0.085);
  let F = 0;
  let whyF = 0;
  let whyLines: string[][] = [];
  let placed: Placed[] = [];
  let whyTop = 0;

  for (let attempt = 0; attempt < 40; attempt++) {
    const whyWords = splitWords(why);
    const whyEm = whyWords.reduce(
      (a, w, k) => a + bW(w) + (k > 0 ? bSpace : 0),
      0,
    );
    whyF = G * 1.08;
    if (whyEm * whyF > avail && avail / whyEm >= Math.max(G * 0.78, H * 0.05)) {
      whyF = avail / whyEm;
    }
    whyLines = balanced(whyWords, bW, bSpace, avail / whyF);
    if (portrait) {
      F = Math.min(H * 0.13, avail / Math.max(...wordEm));
      let y = H * 0.1;
      const stackH = n * F * 0.98;
      let y0 = H * 0.42 - stackH / 2;
      placed = list.map((p) => {
        const gloss = balanced(splitWords(p.gloss), bW, bSpace, avail / G);
        const item: Placed = {
          x0: margin,
          y0,
          x1: margin,
          y1: y,
          colW: avail,
          gloss,
          glossTop: y + F * 1.08,
        };
        y += F * 1.08 + gloss.length * BODY_LH * G + F * 0.42;
        y0 += F * 0.98;
        return item;
      });
      whyTop = Math.max(y + G, H * 0.86 - whyLines.length * BODY_LH * whyF);
      const bottom = whyTop + whyLines.length * BODY_LH * whyF;
      if (bottom <= H * 0.93 || attempt === 39) break;
    } else {
      const sumEm = wordEm.reduce((a, b) => a + b, 0);
      const room = avail - gutter * (n - 1);
      F = Math.min(H * 0.3, room / sumEm);
      const need = wordEm.map((e) => e * F);
      const cols = need.map(() => 0);
      let free = room;
      let open = need.map((_, i) => i);
      for (let pass = 0; pass < n; pass++) {
        const share = free / Math.max(1, open.length);
        const fixedNow = open.filter((i) => need[i] > share);
        if (fixedNow.length === 0) {
          for (const i of open) cols[i] = share;
          break;
        }
        for (const i of fixedNow) {
          cols[i] = need[i];
          free -= need[i];
        }
        open = open.filter((i) => !fixedNow.includes(i));
      }
      const top = H * 0.1;
      const lineW = wordEm.reduce((a, e, i) => a + e + (i > 0 ? nSpace : 0), 0);
      let xNat = (W - lineW * F) / 2;
      let xCol = margin;
      const glossTop = top + F * 1.02;
      placed = list.map((p, i) => {
        const gloss = balanced(
          splitWords(p.gloss),
          bW,
          bSpace,
          (cols[i] - gutter * 0.3) / G,
        );
        const item: Placed = {
          x0: xNat,
          y0: (H - F) / 2,
          x1: xCol,
          y1: top,
          colW: cols[i],
          gloss,
          glossTop,
        };
        xNat += (wordEm[i] + nSpace) * F;
        xCol += cols[i] + gutter;
        return item;
      });
      const glossBottom = Math.max(
        ...placed.map((pl) => pl.glossTop + pl.gloss.length * BODY_LH * G),
      );
      whyTop = H * 0.88 - whyLines.length * BODY_LH * whyF;
      const tall = placed.some((pl) => pl.gloss.length > 4);
      if ((!tall && glossBottom + G * 1.2 <= whyTop) || attempt === 39) break;
    }
    G *= 0.95;
  }

  const move = ease(moveEl.start, moveEl.length, EASE_MOVE);
  // Layout rounds a box and a baseline to whole pixels, so a word carried by
  // `left`/`top` steps along, and one handed back to layout when it stops
  // jumps. It is laid out in its column for its whole life and rides there
  // by transform.
  const moving = move > 0 && move < 1;
  const nodes: React.ReactNode[] = [];

  placed.forEach((pl, i) => {
    const p = list[i];
    const nameEl = tl.get(`name:${i}`);
    const partEl = tl.get(`part:${i}`);
    const inE = ease(nameEl.start, nameEl.length);
    const active = ease(
      partEl.start + partEl.beat("light"),
      partEl.beat("lightIn"),
    );
    const done = ease(whyEl.start + whyEl.beat("light"), whyEl.beat("lightIn"));
    const waiting = ease(
      moveEl.start + moveEl.beat("dim"),
      moveEl.beat("dimIn"),
    );
    const lit = Math.max(active, done);
    const opacity = 1 - (1 - DIM) * waiting * (1 - lit);
    nodes.push(
      <div
        key={`word-${p.word}-${i}`}
        style={{
          position: "absolute",
          left: pl.x1 - F * 0.05,
          top: pl.y1 - F * 0.12,
          transform: `translate(${(pl.x0 - pl.x1) * (1 - move)}px, ${(pl.y0 - pl.y1) * (1 - move)}px)${glide(moving)}`,
          height: F * 1.3,
          paddingLeft: F * 0.05,
          paddingRight: F * 0.12,
          overflow: "hidden",
          fontFamily,
          fontWeight: NAME_W,
          fontSize: F,
          letterSpacing: `${NAME_TRACK}em`,
          lineHeight: `${F * 1.3}px`,
          color: fg,
          opacity,
          whiteSpace: "pre",
        }}
      >
        <span
          style={{
            display: "inline-block",
            transform: `translateY(${((1 - inE) * F * 1.2).toFixed(2)}px)${glide(rising(nameEl.start, nameEl.length, F * 1.2))}`,
          }}
        >
          {p.word}
        </span>
      </div>,
    );

    if (t < partEl.start - 1) return;
    let wi = 0;
    nodes.push(
      <div
        key={`gloss-${i}`}
        style={{
          position: "absolute",
          left: pl.x1 + F * 0.03,
          top: pl.glossTop,
          width: pl.colW + gutter * 0.5,
          fontFamily,
          fontWeight: BODY_W,
          fontSize: G,
          letterSpacing: `${BODY_TRACK}em`,
          lineHeight: `${BODY_LH * G}px`,
          color: fg,
          whiteSpace: "pre",
        }}
      >
        {pl.gloss.map((line) => (
          <div key={line.join(" ")}>
            {line.map((w, k) => {
              const wordEl = tl.get(`gloss:${i}:${wi++}`);
              const e = ease(wordEl.start, wordEl.length);
              return (
                <span
                  key={`${w}-${k}`}
                  style={{
                    display: "inline-block",
                    opacity: e * 0.86,
                    transform: `translateY(${((1 - e) * G * 0.7).toFixed(2)}px)${glide(rising(wordEl.start, wordEl.length, G * 0.7))}`,
                  }}
                >
                  {k > 0 ? ` ${w}` : w}
                </span>
              );
            })}
          </div>
        ))}
      </div>,
    );
  });

  if (why && t >= whyEl.start - 1) {
    let wi = 0;
    nodes.push(
      <div
        key="why"
        style={{
          position: "absolute",
          left: margin + F * 0.03,
          top: whyTop,
          width: avail + whyF,
          fontFamily,
          fontWeight: NAME_W,
          fontSize: whyF,
          letterSpacing: `${BODY_TRACK}em`,
          lineHeight: `${BODY_LH * whyF}px`,
          color: hi,
          whiteSpace: "pre",
        }}
      >
        {whyLines.map((line) => (
          <div key={line.join(" ")}>
            {line.map((w, k) => {
              const wordEl = tl.get(`why:${wi++}`);
              const e = ease(wordEl.start, wordEl.length);
              return (
                <span
                  key={`${w}-${k}`}
                  style={{
                    display: "inline-block",
                    opacity: e,
                    transform: `translateY(${((1 - e) * whyF * 0.7).toFixed(2)}px)${glide(rising(wordEl.start, wordEl.length, whyF * 0.7))}`,
                  }}
                >
                  {k > 0 ? ` ${w}` : w}
                </span>
              );
            })}
          </div>
        ))}
      </div>,
    );
  }

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>{nodes}</ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The name rising word by word, the words moving apart into columns (the
// ones not yet explained dimming), then part by part: the name word lights
// up and its gloss writes in word by word; last, the "why" line writes in
// and every name word lights up. Frames on the 30 fps scene timeline, after
// `delay` and `speed`. The glosses space out to fit the clip. The ids are
// public: a saved `timing` prop refers to them.

export type NameGlossElementId =
  | `name:${number}`
  | "move"
  | `part:${number}`
  | `gloss:${number}:${number}`
  | "why"
  | `why:${number}`;

export interface NameGlossPart {
  word: string;
  gloss: string;
}

export interface NameGlossTimingProps {
  parts?: NameGlossPart[];
  why?: string;
  /** Frames between words as a gloss writes in. */
  stagger?: number;
  /** Frames held on the finished card; the glosses space out to fit the rest. */
  hold?: number;
}

export const DEFAULT_PARTS: NameGlossPart[] = [
  { word: "Brand", gloss: "Your colours, your type, your logo." },
  { word: "kit", gloss: "Packed into every scene you install." },
];
export const DEFAULT_WHY =
  "So the film looks like yours from the first render.";

const NAME_STAGGER = 3;
const NAME_IN = 18;
const NAME_HOLD = 14;
const MOVE = 24;
/** The words not yet explained dim from `DIM_AT` into the move, over `DIM_IN`. */
const DIM_AT = MOVE - 8;
const DIM_IN = 10;
/** The glosses start this long before the move lands. */
const GLOSS_LEAD = 6;
export const WORD_STAGGER = 2;
const WORD_IN = 13;
/** A name word lights `LIGHT_LEAD` before its gloss starts, over `LIGHT_IN`. */
const LIGHT_LEAD = 4;
const LIGHT_IN = 10;
const WHY_AFTER = 28;
/** Frames the "why" line takes to write in, as the spacing counts it. */
const WHY = 24;
/** Every name word lights `DONE_LEAD` before the "why" line, over `DONE_IN`. */
const DONE_LEAD = 6;
const DONE_IN = 14;
export const HOLD = 42;
const MIN_GAP = 18;
const MAX_GAP = 44;

export const splitWords = (s: string) => s.split(/\s+/).filter(Boolean);

/** The parts shown: the given ones, or the defaults when empty. */
export function partsOf(parts: NameGlossPart[]) {
  return parts.length > 0 ? parts : DEFAULT_PARTS;
}

// `name:<i>` rises name word `i`, each following the one before. `move`
// carries the words into their columns; its `dim` and `dimIn` beats dim the
// words still waiting. `part:<i>` is part `i`'s turn: its name word lights
// from its `light` beat (before the start) over `lightIn`, and its gloss
// words `gloss:<i>:<k>` write in, a chain. Parts follow one another, the
// first following the move. `why` lights every name word from its `light`
// beat and its words `why:<k>` write in, following the last part.
export const nameGlossTimeline = defineTimeline<
  NameGlossElementId,
  NameGlossTimingProps
>(
  (
    {
      parts = DEFAULT_PARTS,
      why = DEFAULT_WHY,
      stagger = WORD_STAGGER,
      hold = HOLD,
    },
    { length },
  ) => {
    const list = partsOf(parts);
    const n = list.length;
    const span = length;
    const glossStart = NAME_IN + NAME_HOLD + MOVE - GLOSS_LEAD;
    const fixed = glossStart + WHY_AFTER + WHY + hold;
    const glossGap =
      n > 1
        ? Math.min(MAX_GAP, Math.max(MIN_GAP, (span - fixed) / (n - 1)))
        : 0;
    const glossAt = (i: number) => glossStart + i * glossGap;
    const whyAt = glossAt(n - 1) + WHY_AFTER;
    const moveAt = NAME_IN + NAME_HOLD;

    const elements: TimelineElement<NameGlossElementId>[] = list.map(
      (p, i): TimelineElement<NameGlossElementId> => ({
        id: `name:${i}`,
        lane: "Name",
        label: p.word,
        start: i * NAME_STAGGER,
        length: NAME_IN,
        follows: i > 0 ? `name:${i - 1}` : undefined,
      }),
    );
    elements.push({
      id: "move",
      lane: "Name",
      label: "move",
      start: moveAt,
      length: MOVE,
      follows: n > 0 ? `name:${n - 1}` : undefined,
      beats: { dim: DIM_AT, dimIn: DIM_IN },
    });
    list.forEach((p, i) => {
      const at = glossAt(i);
      elements.push({
        id: `part:${i}`,
        lane: "Parts",
        label: p.word,
        start: at,
        length: i < n - 1 ? glossGap : WHY_AFTER,
        follows: i > 0 ? `part:${i - 1}` : "move",
        beats: { light: -LIGHT_LEAD, lightIn: LIGHT_IN },
      });
      splitWords(p.gloss).forEach((w, k) => {
        elements.push({
          id: `gloss:${i}:${k}`,
          lane: "Glosses",
          label: w,
          start: at + k * stagger,
          length: WORD_IN,
          follows: k > 0 ? `gloss:${i}:${k - 1}` : `part:${i}`,
        });
      });
    });
    elements.push({
      id: "why",
      lane: "Parts",
      label: "why",
      start: whyAt,
      length: WHY,
      follows: n > 0 ? `part:${n - 1}` : "move",
      beats: { light: -DONE_LEAD, lightIn: DONE_IN },
    });
    splitWords(why).forEach((w, k) => {
      elements.push({
        id: `why:${k}`,
        lane: "Why",
        label: w,
        start: whyAt + k * stagger,
        length: WORD_IN,
        follows: k > 0 ? `why:${k - 1}` : "why",
      });
    });
    return elements.sort((a, b) => a.start - b.start);
  },
);
